//! Spec book: build and check the RCE spec book, and verify read receipts.
//! Rust port of the former spec/book/build.py, verify_read.py and
//! receipts_norm.py; output and exit codes are unchanged.
//!
//! The numbered files in spec/book/ are the source of the spec. `build`
//!   * writes a footer `<!-- body-sha256: H -->` on every book file, where H
//!     is the SHA-256 of the file's body (all bytes before the footer line);
//!   * writes INDEX.md (every file with its hash and its read-receipt question);
//!   * writes spec/RCE-SPEC.md, the single-file concatenation of the chapters.
//!
//! Usage: rce-book build [--check] [SPEC_DIR]
//!        rce-book verify RECEIPT.json [SPEC_DIR]   (exit 0 only if all pass)
//!
//! Receipt format (JSON):
//!   {"files": {"00-overview.md": {"sha256": "<hash>", "answer": "<text>"}, ...}}
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

const HEADER: &str = "<!-- Generated by spec/book/build.py from spec/book/*.md. Do not edit this file;\n     edit the book chapters and run `python3 spec/book/build.py`. -->\n\n";

fn sha(s: &str) -> String {
    Sha256::digest(s.as_bytes())
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

/// Python's str.strip()/\s whitespace set.
fn py_ws(c: char) -> bool {
    c.is_whitespace() || ('\u{1c}'..='\u{1f}').contains(&c)
}

/// Normalize an answer: trim, strip `"'. at both ends, lowercase, collapse whitespace.
pub fn norm(a: &str) -> String {
    let a = a
        .trim_matches(py_ws)
        .trim_matches(|c| "`\"'.".contains(c))
        .to_lowercase();
    let mut out = String::new();
    let mut ws = false;
    for c in a.chars() {
        if py_ws(c) {
            ws = true;
        } else {
            if ws {
                out.push(' ');
            }
            ws = false;
            out.push(c);
        }
    }
    if ws {
        out.push(' ');
    }
    out
}

pub fn answer_hash(salt: &str, a: &str) -> String {
    sha(&format!("{salt}\0{}", norm(a)))
}

/// Split text into (body, footer hash) per `\n<!-- body-sha256: H -->\n?\z`.
pub fn split(text: &str) -> (String, Option<String>) {
    let t = text.strip_suffix('\n').unwrap_or(text);
    const P: &str = "\n<!-- body-sha256: ";
    if let Some(rest) = t.strip_suffix(" -->")
        && rest.len() >= 64 + P.len()
    {
        let (pre, h) = rest.split_at(rest.len() - 64);
        if h.bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
            && let Some(body) = pre.strip_suffix(P)
        {
            return (body.to_string(), Some(h.to_string()));
        }
    }
    (format!("{}\n", text.trim_end_matches('\n')), None)
}

fn with_footer(body: &str) -> String {
    format!("{body}\n<!-- body-sha256: {} -->\n", sha(body))
}

pub struct Book {
    pub here: PathBuf,
    pub spec: PathBuf,
}

impl Book {
    pub fn chapters(&self) -> Vec<String> {
        let mut v: Vec<String> = std::fs::read_dir(&self.here)
            .expect("read book dir")
            .flatten()
            .filter_map(|e| e.file_name().into_string().ok())
            .filter(|n| {
                let b = n.as_bytes();
                b.len() > 6
                    && b[0].is_ascii_digit()
                    && b[1].is_ascii_digit()
                    && b[2] == b'-'
                    && n.ends_with(".md")
            })
            .collect();
        v.sort();
        v
    }
    fn read_body(&self, name: &str) -> String {
        split(&std::fs::read_to_string(self.here.join(name)).expect("read chapter")).0
    }
    fn receipts(&self) -> Value {
        serde_json::from_str(
            &std::fs::read_to_string(self.here.join("receipts.json")).expect("receipts.json"),
        )
        .expect("receipts.json is JSON")
    }
    pub fn expected(&self) -> Vec<(PathBuf, String)> {
        let rec = self.receipts();
        let mut out = Vec::new();
        let mut bodies = Vec::new();
        for name in self.chapters() {
            let mut body = self.read_body(&name);
            let q = rec[&name]["question"].as_str().expect("question");
            let block = format!("\n**Read receipt.** {q}\n");
            if !body.contains(block.trim_matches(py_ws)) {
                body.push_str(&block);
            }
            out.push((self.here.join(&name), with_footer(&body)));
            bodies.push(body);
        }
        let mut idx: Vec<String> = [
            "# RCE spec book: index",
            "",
            "Read the chapters in this order. Each ends with the SHA-256 of its body;",
            "an agent proves it read them by following `READ-PROTOCOL.md`.",
            "",
            "| File | Body SHA-256 | Read-receipt question |",
            "|---|---|---|",
        ]
        .map(String::from)
        .to_vec();
        for (i, name) in self.chapters().iter().enumerate() {
            let h = sha(&split(&out[i].1).0);
            let q = rec[name]["question"].as_str().unwrap().replace('|', "\\|");
            idx.push(format!("| `{name}` | `{h}` | {q} |"));
        }
        idx.extend(
            [
                "",
                "The single-file spec `spec/RCE-SPEC.md` is generated from these files.",
                "",
            ]
            .map(String::from),
        );
        out.push((self.here.join("INDEX.md"), with_footer(&idx.join("\n"))));
        out.push((
            self.here.join("READ-PROTOCOL.md"),
            with_footer(&self.read_body("READ-PROTOCOL.md")),
        ));
        out.push((
            self.spec.join("RCE-SPEC.md"),
            format!("{HEADER}{}", rebase_links(&bodies.join("\n---\n\n"))),
        ));
        out
    }
}

/// Rebase relative link and image targets written for a chapter in `book/`
/// so they resolve from `spec/RCE-SPEC.md`: `../x` becomes `x`, `x` becomes
/// `book/x`. Absolute URLs, site paths (`/x`) and anchors (`#x`) are kept.
pub fn rebase_links(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut fenced = false;
    for line in text.split_inclusive('\n') {
        if line.trim_start().starts_with("```") {
            fenced = !fenced;
        }
        if fenced || line.starts_with("    ") || line.starts_with('\t') {
            out.push_str(line);
            continue;
        }
        // Outside code spans (even backtick segments) only.
        for (k, seg) in line.split('`').enumerate() {
            if k > 0 {
                out.push('`');
            }
            if k % 2 == 1 {
                out.push_str(seg);
            } else {
                out.push_str(&rebase_segment(seg));
            }
        }
    }
    out
}

fn rebase_segment(seg: &str) -> String {
    let mut out = String::with_capacity(seg.len());
    let mut rest = seg;
    while let Some(i) = rest.find("](") {
        out.push_str(&rest[..i + 2]);
        rest = &rest[i + 2..];
        let target = &rest[..rest.find(')').unwrap_or(rest.len())];
        let is_path = !target.is_empty()
            && !target.contains(char::is_whitespace)
            && target.contains('.')
            && !target.contains("://")
            && !target.starts_with('/')
            && !target.starts_with('#')
            && !target.starts_with("mailto:");
        if is_path {
            if let Some(r) = rest.strip_prefix("../") {
                rest = r;
            } else {
                out.push_str("book/");
            }
        }
    }
    out.push_str(rest);
    out
}

fn rel(p: &Path, base: &Path) -> String {
    p.strip_prefix(base).unwrap_or(p).display().to_string()
}

pub fn build(b: &Book, check: bool) -> i32 {
    let mut stale = Vec::new();
    for (path, text) in b.expected() {
        let cur = std::fs::read_to_string(&path).ok();
        if cur.as_deref() != Some(text.as_str()) {
            stale.push(rel(&path, &b.spec));
            if !check {
                std::fs::write(&path, text).expect("write");
            }
        }
    }
    if check {
        if !stale.is_empty() {
            println!(
                "book: out of sync: {} (run rce-book build)",
                stale.join(", ")
            );
            return 1;
        }
        println!(
            "book: {} chapters, hashes, INDEX.md and RCE-SPEC.md in sync",
            b.chapters().len()
        );
    } else if stale.is_empty() {
        println!("book: rebuilt nothing (already in sync)");
    } else {
        println!("book: rebuilt {}", stale.join(", "));
    }
    0
}

pub fn verify(b: &Book, receipt: &str) -> i32 {
    let got: Value = serde_json::from_str(&std::fs::read_to_string(receipt).expect("read receipt"))
        .expect("receipt is JSON");
    let files = got
        .get("files")
        .cloned()
        .unwrap_or(Value::Object(Default::default()));
    let rec = b.receipts();
    let mut ok = true;
    let chapters = b.chapters();
    for name in &chapters {
        let want = sha(&b.read_body(name));
        let Some(r) = files.get(name) else {
            println!("MISSING  {name}");
            ok = false;
            continue;
        };
        let s = |k: &str| r.get(k).and_then(Value::as_str).unwrap_or("").to_string();
        let h_ok = s("sha256").trim_matches(py_ws).to_lowercase() == want;
        let a_ok = answer_hash(rec[name]["salt"].as_str().unwrap(), &s("answer"))
            == rec[name]["answer_sha256"].as_str().unwrap();
        let w = |x: bool| if x { "ok" } else { "WRONG" };
        println!(
            "{}  {name}  (hash {}, answer {})",
            if h_ok && a_ok { "PASS" } else { "FAIL" },
            w(h_ok),
            w(a_ok)
        );
        ok &= h_ok && a_ok;
    }
    if let Some(m) = files.as_object() {
        let cs: BTreeSet<&String> = chapters.iter().collect();
        let extra: Vec<&str> = m
            .keys()
            .filter(|k| !cs.contains(k))
            .map(String::as_str)
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect();
        if !extra.is_empty() {
            println!("unknown files in receipt: {}", extra.join(", "));
        }
    }
    println!(
        "read receipt: {}",
        if ok { "VERIFIED" } else { "NOT VERIFIED" }
    );
    if ok { 0 } else { 1 }
}

impl Book {
    /// The book under SPEC_DIR/book.
    pub fn new(spec: &Path) -> Book {
        Book {
            here: spec.join("book"),
            spec: spec.to_path_buf(),
        }
    }
}

#[cfg(test)]
mod rebase_tests {
    #[test]
    fn rebases_relative_targets_only() {
        let t = "![a](../figures/x.svg) [b](09-wellformedness.md) [c](https://e.x/y) [d](#s) [e](/rce/) `f[T](x.y)` g[T](x)";
        assert_eq!(
            super::rebase_links(t),
            "![a](figures/x.svg) [b](book/09-wellformedness.md) [c](https://e.x/y) [d](#s) [e](/rce/) `f[T](x.y)` g[T](x)"
        );
    }
}
